mapper.select:
select sc.id, sc.name, sc.customer_type as customerType, sc.address, sc.card, sc.phone
from sts_customer sc


        sc.name like concat('%', #{name}, '%')


        and sc.card like concat('%', #{card}, '%')


        and sc.customer_type = #{customerType}


        and exists (
        select 1 from warehouse_in_order wio
        where wio.customer_id = sc.id
        and wio.state = #{inStatus}
        )



        and exists (
        select 1 from warehouse_out_order woo
        where woo.customer_id = sc.id
        and woo.state = #{outStatus}
        )


order by sc.add_time desc
